import{_ as l,l as o,o as t,c as n,v as e,p as s,x as r,d as m,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"美式提前行权与最优停","description":"","frontmatter":{"title":"美式提前行权与最优停","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/american-optimal-stop.md","filePath":"quant/american-optimal-stop.md","lastUpdated":1789023840000}'),d={name:"quant/american-optimal-stop.md"};function E(u,a,_,c,B,S){const i=o("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="美式提前行权与最优停" tabindex="-1">美式提前行权与最优停 <a class="header-anchor" href="#美式提前行权与最优停" aria-label="Permalink to &quot;美式提前行权与最优停&quot;">​</a></h1><div class="epigraph"><p>美式价格是停时类上的上确界：$V_0=\\sup_\\tau\\mathbb E_Q[\\mathrm e^{-r\\tau}g(S_\\tau)]$。提前行权当且仅当立即支付超过继续持有的条件期望。</p><footer>—— 据 Bensoussan, Acta Applicandae Mathematicae, 1984；Karatzas, 1988；Shreve, Stochastic Calculus for Finance II, 第 8 章整理</footer></div><p>上一课<a href="/quant/jump-process-intuition">跳过程直觉</a>留下不连续路径的接口。本课回到连续扩散，处理权利本身的时间：美式可在 \\([0,T]\\) 任一停时行权。缺口不是再写一遍欧式期望，而是把<a href="/quant/stopping-optional-sampling">停时与可选抽样</a>里的 \\(\\tau\\) 拿来做优化。本课只给最优停与 Snell 包络接口，不把自由边界数值做完；后课蒙特卡洛会用这条上确界当模拟对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧式把 \\(\\tau\\) 钉死为 \\(T\\)。美式允许持有人选 \\(\\tau\\le T\\)，价格是对所有停时取上确界。缺口是：这个上确界满足 \\(V_t=\\max\\bigl(g(S_t),\\,\\mathrm e^{-r\\Delta}\\mathbb E[V_{t+\\Delta}\\mid\\mathcal F_t]\\bigr)\\)（离散骨架），连续极限是变分不等式 \\(V\\ge g\\)，PDE 在继续区域内成立，在行权区域内取等 \\(V=g\\)。没有最优停，美式被误写成欧式再加一个「可能提前」的口头修正。</p><p>无股息看涨：在常数 \\(r\\gt 0\\) 下永不提前行权，美式等于欧式。看跌、有股息看涨，提前可能最优。这是接口，不是要在本课证完。</p><h3 id="最优停不是「看到最高点再行权」" tabindex="-1">最优停不是「看到最高点再行权」 <a class="header-anchor" href="#最优停不是「看到最高点再行权」" aria-label="Permalink to &quot;最优停不是「看到最高点再行权」&quot;">​</a></h3><p>那不是停时。最优 \\(\\tau^*\\) 是首次进入行权区域的时刻，区域由当时的 \\(S\\) 与剩余期限决定，不依赖未来路径。与停时课的反例同一条：不能用尚未实现的最大值。</p><p><span class="marginnote">Snell 包络是 supermartingale 的最小上界过程，在最优停时变成鞅。可选抽样保证：乱停只会更差或持平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(V_t=\\mathrm{ess\\,sup}_{\\tau\\in[t,T]}\\mathbb E_Q[\\mathrm e^{-r(\\tau-t)}g(S_\\tau)\\mid\\mathcal F_t]\\)。继续值 \\(C_t=\\mathbb E_Q[\\mathrm e^{-r\\mathrm d t}V_{t+\\mathrm d t}\\mid\\mathcal F_t]\\)，行权当 \\(g(S_t)\\ge C_t\\)。BSM 扩散下存在临界价 \\(S^*(t)\\)：看跌在 \\(S\\le S^*(t)\\) 行权。这是后课差分、树、Longstaff–Schwartz 回归的共同对象：都在近似 \\(C_t\\)。</p><p>跳会让区域出现「无触摸」带（跳跃越过边界），本课不展开，只声明接口仍是对停时取上确界，搜索空间没变。</p>',12)),(t(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%81%9C%E6%97%B6%E7%B1%BB%22%5D%20--%3E%20SUP%5B%22%E4%B8%8A%E7%A1%AE%E7%95%8C%E5%8D%B3%E7%BE%8E%E5%BC%8F%E4%BB%B7%22%5D%0A%20%20SUP%20--%3E%20SNELL%5B%22Snell%20%E5%8C%85%E7%BB%9C%22%5D%0A%20%20SNELL%20--%3E%20EX%5B%22g%20%E5%A4%A7%E4%BA%8E%E7%BB%A7%E7%BB%AD%E5%80%BC%E5%88%99%E8%A1%8C%E6%9D%83%22%5D%0A%20%20SUP%20--%3E%20MC%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B7%AF%E5%BE%84%E4%B8%8A%E4%BC%B0%E8%AE%A1%E7%BB%A7%E7%BB%AD%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>继续值是「再等一瞬间」的复制价格，欧式课已经会算条件期望。美式多一个逐点 \\(\\max(g,\\cdot)\\)，破坏了纯 PDE 等式，改成互补：\\((V-g)\\cdot(\\text{PDE 残差})=0\\)。对冲在边界上 \\(\\Delta\\) 可能折拐（平滑粘贴在扩散情形常成立），Gamma 在边界附近变大。这是与欧式 delta 的差别，不是新的测度。离散时间把上确界收成从 \\(T\\) 向后的动态规划，树方法做的就是这件事；连续极限只是把网格加密。</p><p>无套利：美式价必须 \\(\\ge\\) 欧式价，且 \\(\\ge g\\mathrm e^{-r\\cdot 0}=g\\)（立即行权）。低于内在价值的报价可被立即行权套利。这不依赖 GBM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现最小二乘蒙特卡洛，不画自由边界的渐近。不把百慕大、可转债的条款写全。后课默认：美式 $= $停时上确界；欧式是 \\(\\tau\\equiv T\\) 的特例；无股息看涨不提前。下一课<a href="/quant/mc-paths">蒙特卡洛路径</a>用模拟估计期望；美式需要在同一路径对象上再估继续值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美式价格是贴现支付在停时类上的上确界。</li><li>行权当立即支付不低于继续值；最优 \\(\\tau\\) 是首入行权区。</li><li>无股息看涨通常不提前；看跌与股息看涨会。</li><li>跳不改变上确界定义，只改变区域形状。</li><li>出处：Bensoussan 1984；Karatzas 1988；Shreve SDE II 第 8 章。</li></ul>',7))])}const f=l(d,[["render",E]]);export{g as __pageData,f as default};
